@using sv_92d2e171ce4540429e96502353247aa9.Models

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i;
        var css = step == CurrentStep ? "step active"
                : step < CurrentStep ? "step completed"
                : "step future";

        <div class="@css" @onclick="() => OnStepClick(step)">
            <div class="step-circle">
                @if (step < CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[step]</div>
        </div>

        @if (step < StepNames.Length - 1)
        {
            <div class="step-connector @(step < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnNavigate { get; set; }

    private async Task OnStepClick(int step)
    {
        // Only allow navigating to completed steps
        if (step < CurrentStep)
        {
            await OnNavigate.InvokeAsync(step);
        }
    }
}

@using sv_92d2e171ce4540429e96502353247aa9.Models

<div class="work-entry-card">
    <div class="card-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" class="form-control" value="@Company"
                   @onchange="e => { Company = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" class="form-control" value="@Title"
                   @onchange="e => { Title = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => { if (DateTime.TryParse(e.Value?.ToString(), out var d)) { StartDate = d; NotifyChanged(); } }" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => { if (DateTime.TryParse(e.Value?.ToString(), out var d)) { EndDate = d; NotifyChanged(); } }" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Description"
                  @onchange="e => { Description = e.Value?.ToString() ?? ""; NotifyChanged(); }"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public WorkEntry? Entry { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private string Company = "";
    private string Title = "";
    private DateTime StartDate = DateTime.Today;
    private DateTime? EndDate;
    private bool IsCurrent;
    private string Description = "";

    protected override void OnParametersSet()
    {
        if (Entry is not null)
        {
            Company = Entry.Company;
            Title = Entry.Title;
            StartDate = Entry.StartDate;
            EndDate = Entry.EndDate;
            IsCurrent = Entry.EndDate is null && !string.IsNullOrEmpty(Entry.Company);
            Description = Entry.Description;
        }
    }

    private async Task NotifyChanged()
    {
        var entry = new WorkEntry(Company, Title, StartDate, IsCurrent ? null : EndDate, Description);
        await OnEntryChanged.InvokeAsync(entry);
    }
}

@using sv_92d2e171ce4540429e96502353247aa9.Models

<div class="reference-card">
    <div class="card-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
