@using sv_92d2e171ce4540429e96502353247aa9.Models

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" class="form-control" value="@FullName"
               @onchange="e => FullName = e.Value?.ToString() ?? "" " />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" class="form-control" value="@Email"
               @onchange="e => Email = e.Value?.ToString() ?? "" " />
        @if (IsValidatingEmail)
        {
            <span class="validation-hint">Validating email...</span>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" class="form-control" value="@Phone"
                   @onchange="e => Phone = e.Value?.ToString() ?? "" " />
        </div>
        <div class="form-group">
            <label>Address *</label>
            <input type="text" class="form-control" value="@Address"
                   @onchange="e => Address = e.Value?.ToString() ?? "" " />
        </div>
    </div>

    <div class="step-buttons">
        <div></div>
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidatingEmail">Next</button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Info { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string FullName = "";
    private string Email = "";
    private string Phone = "";
    private string Address = "";
    private string ErrorMessage = "";
    private bool IsValidatingEmail;

    protected override void OnParametersSet()
    {
        if (Info is not null)
        {
            FullName = Info.FullName;
            Email = Info.Email;
            Phone = Info.Phone;
            Address = Info.Address;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = "";

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidatingEmail = true;
        StateHasChanged();

        try
        {
            var isValid = ValidateEmail is not null && await ValidateEmail(Email);
            if (!isValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            IsValidatingEmail = false;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

@using sv_92d2e171ce4540429e96502353247aa9.Models

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Index="index"
                       Entry="Entries[index]"
                       CanRemove="Entries.Count > 1"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-primary" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public WorkHistory? History { get; set; }
    [Parameter] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> Entries = new();
    private string ErrorMessage = "";

    protected override void OnParametersSet()
    {
        if (History?.Entries is { Count: > 0 })
        {
            Entries = History.Entries.ToList();
        }
        else if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        }
    }

    private void UpdateEntry(int index, WorkEntry entry)
    {
        Entries[index] = entry;
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = "";

        if (Entries.Any(e => string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title)))
        {
            ErrorMessage = "Each position requires at least a company name and job title.";
            return;
        }

        await OnNext.InvokeAsync(new WorkHistory(Entries.ToList()));
    }
}

@using sv_92d2e171ce4540429e96502353247aa9.Models

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Index="index"
                       Entry="References[index]"
                       CanRemove="References.Count > 2"
                       OnEntryChanged="e => UpdateReference(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-primary" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? ExistingReferences { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> References = new();
    private string ErrorMessage = "";

    protected override void OnParametersSet()
    {
        if (ExistingReferences is { Count: > 0 })
        {
            References = ExistingReferences.ToList();
        }
        else if (References.Count == 0)
        {
            References.Add(new Reference("", "", "", ""));
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void UpdateReference(int index, Reference reference)
    {
        References[index] = reference;
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = "";

        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email)))
        {
            ErrorMessage = "Each reference requires at least a name and email.";
            return;
        }

        await OnNext.InvokeAsync(References.ToList());
    }
}

@using sv_92d2e171ce4540429e96502353247aa9.Models

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <div class="review-grid">
                    <div><strong>Name:</strong> @Personal.FullName</div>
                    <div><strong>Email:</strong> @Personal.Email</div>
                    <div><strong>Phone:</strong> @Personal.Phone</div>
                    <div><strong>Address:</strong> @Personal.Address</div>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @if (Work?.Entries is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="review-work-entry">
                        <div><strong>@entry.Title</strong> at @entry.Company</div>
                        <div>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</div>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <div class="review-description">@entry.Description</div>
                        }
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-reference">
                        <div><strong>@r.Name</strong> (@r.Relationship)</div>
                        <div>@r.Email &bull; @r.Phone</div>
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <div class="review-cover-letter">@CoverLetter</div>
        </div>

        <div class="step-buttons">
            <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
