arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_92d2e171ce4540429e96502353247aa9.Models
@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnNavigate="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Info="personalInfo"
                              ValidateEmail="AppService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep History="workHistory"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep ExistingReferences="references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo"
                        Work="workHistory"
                        References="references"
                        CoverLetter="coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private PersonalInfo? personalInfo;
    private WorkHistory? workHistory;
    private List<Reference>? references;
    private string coverLetter = "";

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        currentStep = 1;
    }

    private void HandleWorkNext(WorkHistory history)
    {
        workHistory = history;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo!,
            workHistory!,
            references!,
            coverLetter
        );
        return await AppService.SubmitApplicationAsync(application);
    }
}

.application-container {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-container h2 {
    text-align: center;
    margin-bottom: 2rem;
    color: #333;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    white-space: nowrap;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    margin: 0 0.5rem;
