toolArgs.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_92d2e171ce4540429e96502353247aa9.Models
@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnNavigate="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Info="personalInfo"
                              ValidateEmail="AppService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep History="workHistory"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep ExistingReferences="references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo"
                        Work="workHistory"
                        References="references"
                        CoverLetter="coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private PersonalInfo? personalInfo;
    private WorkHistory? workHistory;
    private List<Reference>? references;
    private string coverLetter = "";

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        currentStep = 1;
    }

    private void HandleWorkNext(WorkHistory history)
    {
        workHistory = history;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo!,
            workHistory!,
            references!,
            coverLetter
        );
        return await AppService.SubmitApplicationAsync(application);
    }
}

